      {label = "Douse the fire.", tooltip = "", outcomes = {"EV21_douse_dormice", "EV21_douse_smoke", "EV21_douse_smoke", "EV21_douse_burn"}},
      {label = "Walk on.", tooltip = "", outcomes = {"EV21_walk_falls", "EV21_walk_ring"}},
    },
  },
  ["EV21_reach_hilt"] = {
    title = "Warm Hilt",
    flavor = "You wrap your arm in a cloak and reach in past the flames. The fire bites your leader's sleeve, but your fingers close on something heavy and well made, still warm from the heart of the tree.",
    effect = "Party gains a rare item. Leader takes 1 damage.",
    options = {},
  },
  ["EV21_reach_tin"] = {
    title = "Tin Box",
    flavor = "You wrap your arm in a cloak and reach in past the flames. Your fingers close on a tin box, hot to the touch. Inside are coins someone hid in the tree a long time ago.",
    effect = "Party gains 20 gold.",
    options = {},
  },
  ["EV21_wait_lantern"] = {
    title = "Cracked Lantern",
    flavor = "You make camp in the rain and wait for the oak to burn down. By morning it's ash. In the hollow, blackened but whole, is whatever the tree was keeping.",
    effect = "Party gains a random item.",
    options = {},
  },
  ["EV21_wait_lump"] = {
    title = "Was a Bell",
    flavor = "You make camp in the rain and wait for the oak to burn down. By morning it's ash. The thing in the hollow was a bell. Now it's a lump, though the metal will still sell.",
    effect = "Party gains 5 gold.",
    options = {},
  },
  ["EV21_wait_gone"] = {
    title = "Beaten to It",
    flavor = "You make camp in the rain and wait for the oak to burn down. By morning it's ash, and someone else has been and gone. Their tracks are fresh.",
    effect = "",
    options = {},
  },
  ["EV21_douse_dormice"] = {
    title = "Neighbors",
    flavor = "You haul water from the puddles and set to dousing the fire. Dormice watching from the next tree come down to help. When it's out, they thank you and show you what's inside.",
    effect = "Party gains 1 Favor and a random item.",
    options = {},
  },
  ["EV21_douse_smoke"] = {
    title = "All Smoke",
    flavor = "You haul water from the puddles and set to dousing the fire. You make a great deal of smoke and very little progress.",
    effect = "",
    options = {},
  },
  ["EV21_douse_burn"] = {
    title = "It Fights Back",
    flavor = "You haul water from the puddles and set to dousing the fire. The fire fights back, spitting sparks and hot sap until you give up, singed.",
    effect = "Party takes 1 damage.",
    options = {},
  },
  ["EV21_walk_falls"] = {
    title = "Down It Comes",
    flavor = "You leave the oak to burn and walk on. Behind you, it groans and comes down.",
    effect = "",
    options = {},
  },
  ["EV21_walk_ring"] = {
    title = "It Rang",
    flavor = "You leave the oak to burn and walk on. Behind you, it groans and comes down. Something inside rings like a bell as it lands, and you hear it long after you should be out of earshot.",
    effect = "Add a Curse to the party deck.",
    options = {},
  },
  ["EV22"] = {
    title = "Something Circling",
    template = "event_wood_template",
    flavor = "Your fire is down to coals when you hear it: footsteps, circling the camp, just past the light. They stop when you stop talking. They start again when you do.",
    effect = "",
    options = {
      {label = "Throw on more wood.", tooltip = "", outcomes = {"EV22_wood_fade", "EV22_wood_kit"}},
      {label = "Call out to it.", tooltip = "", outcomes = {"EV22_call_peddler", "EV22_call_rush", "EV22_call_quiet"}},
      {label = "Spot it first.", tooltip = "[AGI 1]", outcomes = {"EV22_spot_kit", "EV22_spot_weasel"}},
      {label = "Pretend to sleep.", tooltip = "", outcomes = {"EV22_sleep_acorn", "EV22_sleep_real", "EV22_sleep_wait"}},
    },
  },
  ["EV22_wood_fade"] = {
    title = "Nobody Sleeps",
    flavor = "You throw on more wood until the fire roars. The footsteps fade back into the dark. Nobody sleeps much after that.",
    effect = "Party is Exhausted.",
    options = {},
  },
  ["EV22_wood_kit"] = {
    title = "Working Up the Nerve",
    flavor = "You throw on more wood until the fire roars. In the bigger light you see a starving fox kit who has been working up the nerve to ask. You share your supper with her.",
    effect = "Party loses 1 ration. Party gains 1 Favor.",
    options = {},
  },
  ["EV22_call_peddler"] = {
    title = "Shy Peddler",
    flavor = "You call out into the dark. A peddler steps into the light, embarrassed, her pack still on her back. She sells you something before she goes, and does not lower her price.",
    effect = "Party loses 10 gold. Party gains a random item.",
    options = {},
  },
  ["EV22_call_rush"] = {
    title = "It Answers",
    flavor = "You call out into the dark. It answers by rushing the fire.",
    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV22_call_quiet"] = {
    title = "Never Found Out",
    flavor = "You call out into the dark. The footsteps stop and don't start again. You never find out what it was.",
    effect = "",
    options = {},
  },
  ["EV22_spot_kit"] = {
    title = "Fox Kit",
    flavor = "You slip away from the fire and circle out after it. It's a starving fox kit, too scared to ask. You feed her, and by morning she has left a gift beside the coals.",
    effect = "Party loses 1 ration. Party gains 1 Favor and a random item.",
    options = {},
  },
  ["EV22_spot_weasel"] = {
    title = "Caught Halfway",
    flavor = "You slip away from the fire and circle out after it. You catch a weasel halfway into your packs. He bolts and leaves everything behind, his own purse included.",
    effect = "Party gains 15 gold.",
    options = {},
  },
  ["EV22_sleep_acorn"] = {
    title = "A Fair Trade",
    flavor = "You bank the fire, lie down, and pretend to sleep. Something creeps in, takes a ration, and leaves a single acorn in its place.",
    effect = "Party loses 1 ration.",
    options = {},
  },
  ["EV22_sleep_real"] = {
    title = "Too Convincing",
    flavor = "You bank the fire, lie down, and pretend to sleep. You pretend so well that you actually sleep, and nothing happens.",
    effect = "Party heals 2.",
    options = {},
  },
  ["EV22_sleep_wait"] = {
    title = "It Waited",
    flavor = "You bank the fire, lie down, and pretend to sleep. It waits until you're really asleep.",
    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV23"] = {
    title = "The Beaver Dam",
    template = "event_water_template",
    flavor = "A beaver dam has backed the stream up over the road. On top of it, an old beaver is shouting instructions at a young one, who is shouting back. Neither of them is fixing the leak spraying out of the middle.",
    effect = "",
    options = {
      {label = "Haul timber.", tooltip = "[STR 1]", outcomes = {"EV23_haul_fish", "EV23_haul_road"}},
      {label = "Fix the design.", tooltip = "[INT 1]", outcomes = {"EV23_design_thrilled", "EV23_design_thrilled", "EV23_design_offended"}},
      {label = "Wade the flood.", tooltip = "", outcomes = {"EV23_wade_cold", "EV23_wade_rations", "EV23_wade_burst"}},
      {label = "Settle the argument.", tooltip = "", outcomes = {"EV23_settle_young", "EV23_settle_old", "EV23_settle_both"}},
    },
  },
  ["EV23_haul_fish"] = {
    title = "Paid in Fish",
    flavor = "You haul timber up the dam and jam it into the leak. The spray slows, then stops. The old beaver pays you in smoked fish, and takes the credit.",
    effect = "Party gains 3 rations.",
    options = {},
  },
  ["EV23_haul_road"] = {
    title = "Road Clear",
    flavor = "You haul timber up the dam and jam it into the leak. The leak closes, and the water drops enough to clear the road.",
    effect = "Party saves 1 day.",
    options = {},
  },
  ["EV23_design_thrilled"] = {
    title = "He Knew That",
    flavor = "You study the dam and point out where it's weak. The young one is thrilled and has it patched in no time. The old one says he knew that.",
    effect = "Party gains 1 Favor. Party saves 1 day.",
    options = {},
  },
  ["EV23_design_offended"] = {
    title = "Deeply Offended",
    flavor = "You study the dam and point out where it's weak. The old beaver is deeply offended. The leak stays, on principle.",
    effect = "",
    options = {},
  },
  ["EV23_wade_cold"] = {
    title = "Knee-Deep",
    flavor = "You wade into the flood with your packs held high. It's knee-deep and cold, but passable.",
    effect = "",
    options = {},
  },
  ["EV23_wade_rations"] = {
    title = "Soggy",
    flavor = "You wade into the flood with your packs held high. Not high enough. Your rations don't survive the trip.",
    effect = "Party loses 2 rations.",
    options = {},
  },
  ["EV23_wade_burst"] = {
    title = "The Dam Gives",
    flavor = "You wade into the flood with your packs held high. Halfway across, the dam picks that moment to give. The water knocks you off your feet, and something from your packs goes downstream.",
    effect = "Party takes 1 damage. Party loses a random item.",
    options = {},
  },
  ["EV23_settle_young"] = {
    title = "The Young One",
    flavor = "You climb up between them to settle it. You side with the young one. The old one storms off, and the leak is fixed in a minute.",
    effect = "Party saves 1 day.",
    options = {},
  },
  ["EV23_settle_old"] = {
    title = "The Old One",
    flavor = "You climb up between them to settle it. You side with the old one. He's so pleased he forgets the leak entirely, and you wait half the day for the water to drop.",
    effect = "Party loses 1 day.",
    options = {},
  },
  ["EV23_settle_both"] = {
    title = "United Front",
    flavor = "You climb up between them to settle it. Before you can pick a side, they both turn on you.",
    effect = "",
    options = {},
  },
  ["EV24"] = {
    title = "Moss Helmets",
    template = "event_scar_template",
    flavor = "The ground here is quiet and overgrown. It takes a moment to see that the mounds under the moss are helmets, hundreds of them, cat and bird alike. Someone has been here recently. A path is worn between the mounds, and a few have been pried open.",
    effect = "",
    options = {
      {label = "Search the field.", tooltip = "", outcomes = {"EV24_search_blade", "EV24_search_taken", "EV24_search_scav", "EV24_search_rust"}},
      {label = "Follow the worn path.", tooltip = "", outcomes = {"EV24_path_widow", "EV24_path_camp", "EV24_path_out"}},
      {label = "Pay your respects.", tooltip = "", outcomes = {"EV24_respect_bless", "EV24_respect_quiet"}},
    },
  },
  ["EV24_search_blade"] = {
    title = "Never Drawn",
    flavor = "You move between the mounds, pulling back moss and lifting helmets. Under one lies a sword still in its scabbard, never drawn.",
    effect = "Party gains a random item.",
    options = {},
  },
  ["EV24_search_taken"] = {
    title = "Not Yours",
    flavor = "You move between the mounds, pulling back moss and lifting helmets. Beneath one, you find something worth keeping, and take it. Only later do you notice the name scratched inside.",
    effect = "Party gains a random item. Add a Curse to the party deck.",
    options = {},
  },
  ["EV24_search_scav"] = {
