    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV24_search_rust"] = {
    title = "Rust and Moss",
    flavor = "You move between the mounds, pulling back moss and lifting helmets. There's rust and moss, and nothing else.",
    effect = "",
    options = {},
  },
  ["EV24_path_widow"] = {
    title = "Every Week",
    flavor = "You follow the worn path between the mounds. It leads to an old cat who comes here every week. She asks you to help her find one helmet in particular, and you spend the day looking. When you find it, she sits down beside it.",
    effect = "Party loses 1 day. Party gains 2 Favors.",
    options = {},
  },
  ["EV24_path_camp"] = {
    title = "Scavenger Camp",
    flavor = "You follow the worn path between the mounds. It leads to a camp of scavengers, and they don't like visitors.",
    effect = "Start a combat encounter.",
    options = {},
  },
  ["EV24_path_out"] = {
