    flavor = "You put your coin on one village and watch the rope. Your side loses, badly.",
    effect = "",
    options = {},
  },
  ["EV25_fair_rest"] = {
    title = "Pies and Hay",
    flavor = "You leave the rope to the villagers and spend the day at the fair. There are pies and music, and at night a soft patch of hay.",
    effect = "Party heals fully.",
    options = {},
  },
  ["EV25_fair_pockets"] = {
