    effect = "",
    options = {},
  },
  ["EV26_answer_found"] = {
    title = "Now It Knows",
    flavor = "You call back. The calling stops. A moment later, much closer, it says your name again.",
    effect = "Party gains 1 Pursuit.",
    options = {},
  },
  ["EV26_wait_empty"] = {
    title = "Nobody There",
    flavor = "You sit tight and wait for the fog to lift. By noon it does, and nobody is there.",
    effect = "",
    options = {},
  },
  ["EV26_wait_prints"] = {
