    effect = "Party gains 1 Favor.",
    options = {},
  },
  ["EV27_turn_bounty"] = {
    title = "Bounty",
    flavor = "You call up the hill, and the sergeant comes down for him. She counts out a bounty and doesn't look at either of you.",
    effect = "Party gains 15 gold and 1 Marquisate reputation.",
    options = {},
  },
  ["EV27_turn_look"] = {
