    effect = "Party loses 10 gold. Party gains 1 Favor.",
    options = {},
  },
  ["EV27_leave_empty"] = {
    title = "Empty Log",
    flavor = "You walk on and leave him in his ditch. When you look back, the ditch is empty.",
    effect = "",
    options = {},
  },
  ["EV27_leave_shout"] = {
    title = "The Shout",
    flavor = "You walk on and leave him in his ditch. Behind you, someone shouts, and you don't look back.",
    effect = "Add a Curse to the party deck.",
    options = {},
  },
