      {label = "Break the cipher.", tooltip = "[INT 2]", outcomes = {"EV28_cipher_orders", "EV28_cipher_love"}},
      {label = "Take the letter.", tooltip = "", outcomes = {"EV28_take_sold", "EV28_take_hunted"}},
      {label = "Carry him to a post.", tooltip = "Decrement Time count.", outcomes = {"EV28_carry_paid", "EV28_carry_questions"}},
    },
  },
  ["EV28_splint_name"] = {
